import{r}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as n,o as s,c as t,b6 as i,J as d,k as l}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"De la idea al producto de IA - Ruta de aprendizaje de Easy-Vibe","description":"Ruta de aprendizaje completa de programación con IA: de cero al desarrollo fullstack. Domina Vibe Coding, Claude Code, Cursor y otras herramientas AI IDE, aprende pensamiento de producto, desarrollo fullstack e integración de capacidades de IA.","frontmatter":{"title":"De la idea al producto de IA - Ruta de aprendizaje de Easy-Vibe","description":"Ruta de aprendizaje completa de programación con IA: de cero al desarrollo fullstack. Domina Vibe Coding, Claude Code, Cursor y otras herramientas AI IDE, aprende pensamiento de producto, desarrollo fullstack e integración de capacidades de IA."},"headers":[],"relativePath":"es-es/stage-1/learning-map/index.md","filePath":"es-es/stage-1/learning-map/index.md"}'),c={name:"es-es/stage-1/learning-map/index.md"},h=Object.assign(c,{setup(p){const a=r["es-es/stage-1/learning-map"]??[];return(u,e)=>{const o=n("RelatedArticlesSection");return s(),t("div",null,[e[0]||(e[0]=i('<h1 id="de-la-idea-al-producto-de-ia" tabindex="-1">De la idea al producto de IA <a class="header-anchor" href="#de-la-idea-al-producto-de-ia" aria-label="Permalink to “De la idea al producto de IA”">​</a></h1><div class="info custom-block"><p class="custom-block-title">Agradecimiento especial</p><p>¡Un agradecimiento especial a los estudiantes de la <strong>Universidad de Tsinghua, Campus de Shenzhen</strong> por sus pruebas, retroalimentación y apoyo a este curso! Sus opiniones y contribuciones han hecho que este curso sea mejor. <a href="https://github.com/datawhlechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 Ver lista completa de contribuyentes</a></p></div><p>Antes, crear software tenía una barrera muy alta: necesitabas saber programar, entender algoritmos y tener años de experiencia en proyectos. Ahora es diferente. Mientras tengas una idea, la IA puede ayudarte a escribir código.</p><p>Este es un cambio enorme: <strong>los lenguajes de programación se están convirtiendo en lenguaje natural</strong>.</p><p>La aparición de los modelos de lenguaje grande (LLM) ha hecho que el desarrollo ya no sea &quot;exclusivo de los gurús técnicos&quot;, sino una herramienta que todos pueden utilizar. Antes, lo más difícil era &quot;cómo escribir código&quot;; ahora, lo más difícil es &quot;<strong>qué quieres hacer</strong>&quot;.</p><blockquote><p><strong>¿Qué es Vibe Coding?</strong> En pocas palabras, es &quot;programar hablando&quot;. Vibe coding significa que puedes depender únicamente de conversar con la IA, en lugar de escribir código directamente, para completar proyectos de programación.</p></blockquote><p>Por supuesto, hacer que la IA escriba código es solo el primer paso. Para crear un producto realmente funcional, aún te enfrentarás a estas preguntas:</p><ul><li>¿Cómo hacer que la IA escriba código limpio y mantenible?</li><li>¿Cómo unir código disperso en una aplicación funcional?</li><li>¿Cómo poner la aplicación realmente en línea y que la gente la use?</li><li>¿Cómo integrar capacidades de IA como generación de texto y reconocimiento de imágenes en tu producto?</li></ul><p>Estas preguntas encontrarán respuesta en este curso.</p><p>No importa si eres estudiante, profesor, médico, trabajador o cualquier persona sin conocimientos técnicos, no necesitas aprender a programar durante años; en dos semanas podrás crear un prototipo de producto funcional y demostrable.</p><table tabindex="0"><thead><tr><th>Tu perfil</th><th>Lo que este curso puede hacer por ti</th></tr></thead><tbody><tr><td>Estudiante</td><td>Tareas, competiciones, emprendimiento; haz tus propios proyectos sin depender de nadie</td></tr><tr><td>Profesional</td><td>Automatiza trabajos repetitivos, mejora tu eficiencia e incluso desarrolla un negocio secundario</td></tr><tr><td>Product Manager / Diseñador</td><td>Tus ideas ya no se quedan en papel; puedes crear demos rápidamente para tu jefe/clientes</td></tr><tr><td>Emprendedor / PyME</td><td>Valida ideas a bajo costo; puedes crear un MVP sin gastar miles en outsourcing</td></tr><tr><td>Profesor / Educador</td><td>Crea herramientas didácticas, presentaciones y evaluaciones automatizadas, mejorando la eficiencia educativa</td></tr><tr><td>Médico / Abogado / Profesional</td><td>Automatiza procesos profesionales y crea tus propias herramientas de eficiencia</td></tr><tr><td>Cualquier persona</td><td>Usa IA para resolver problemas específicos de tu vida/trabajo, haciendo lo imposible posible</td></tr></tbody></table><p>En la era de la IA, la capacidad de ejecución y las ideas siempre son más importantes que la tecnología.</p><h2 id="ruta-de-crecimiento-de-saber-usar-ia-a-saber-crear-productos-de-ia" tabindex="-1">Ruta de crecimiento: de &quot;saber usar IA&quot; a &quot;saber crear productos de IA&quot; <a class="header-anchor" href="#ruta-de-crecimiento-de-saber-usar-ia-a-saber-crear-productos-de-ia" aria-label="Permalink to “Ruta de crecimiento: de &quot;saber usar IA&quot; a &quot;saber crear productos de IA&quot;”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>Introducción</h3><p class="stage-role">Experimenta la programación con IA</p><div class="stage-tags"><span>Mini juego Snake</span><span>Inicio desde cero</span><span>Primera experiencia de Vibecoding</span><span>Generación en minutos</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>Primera Etapa</h3><p class="stage-role">Product Manager / Operaciones</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>Descomposición de requisitos y prototipo</span><span>Integración de capacidades de IA</span><span>Desarrollo de Demo completo</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>Segunda Etapa</h3><p class="stage-role">Desarrollador junior/intermedio / Desarrollador independiente</p><div class="stage-tags"><span>De Figma a código</span><span>Base de datos Supabase</span><span>Integración de pago Stripe</span><span>Base de conocimientos Dify</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>Tercera Etapa</h3><p class="stage-role">Desarrollador senior / Arquitecto</p><div class="stage-tags"><span>Web/Mini-programas/Multiplataforma</span><span>Herramientas avanzadas MCP</span><span>RAG y LangGraph</span><span>Mentalidad de ingeniero senior</span></div></div></div><p>A través de esta ruta de aprendizaje completa, obtendrás:</p><ul><li><strong>Capacidad de desarrollo Vibe Coding:</strong> Domina la mentalidad de vibecoding y las herramientas de codificación con IA, multiplicando tu eficiencia de desarrollo. Ya no necesitas memorizar sintaxis, sino aprender a guiar la IA para generar código de alta calidad.</li><li><strong>Habilidades de desarrollo fullstack:</strong> Desde el diseño UI hasta la implementación frontend, desde el diseño de base de datos hasta el desarrollo de API, desde el desarrollo local hasta el despliegue en la nube, domina la pila tecnológica completa de aplicaciones web modernas.</li><li><strong>Integración de capacidades de IA:</strong> Aprende a llamar a diversas APIs multimodales de IA, integrando capacidades de IA como texto, imagen y voz en tus aplicaciones, y construyendo productos inteligentes a través de tecnologías como RAG.</li><li><strong>Pensamiento de producto y capacidad operativa:</strong> Desde la investigación de usuarios hasta la descomposición de requisitos, desde el diseño de MVP hasta la iteración del producto, desde la integración de pagos hasta la gestión de usuarios, formando un ciclo completo de desarrollo y operación de productos.</li></ul><h1 id="¿que-podras-hacer-al-terminar" tabindex="-1">¿Qué podrás hacer al terminar? <a class="header-anchor" href="#¿que-podras-hacer-al-terminar" aria-label="Permalink to “¿Qué podrás hacer al terminar?”">​</a></h1><h2 id="primera-etapa-crea-tu-primer-prototipo-de-producto" tabindex="-1">Primera Etapa: Crea tu primer prototipo de producto <a class="header-anchor" href="#primera-etapa-crea-tu-primer-prototipo-de-producto" aria-label="Permalink to “Primera Etapa: Crea tu primer prototipo de producto”">​</a></h2><p>Esta etapa es adecuada para personas que no tienen ninguna base de programación, o que solo saben un poco pero no se sienten seguras. No necesitas aprender mucha teoría primero; en su lugar, sigue los pasos directamente y aprende a usar herramientas de IA para escribir código mientras lo haces.</p><p><strong>Al terminar podrás</strong>:</p><ul><li>Completar independientemente una aplicación web con herramientas de programación con IA</li><li>Convertir ideas de producto en prototipos clicables e interactivos</li><li>Añadir funcionalidades de IA al prototipo (como generación de imágenes desde texto, chat inteligente)</li><li>Saber cómo diagnosticar y resolver errores cuando aparezcan</li></ul><p>En pocas palabras, podrás crear algo &quot;que funcione y que puedas demostrar a otros&quot;.</p><p>Podemos primero experimentar la programación con IA a través de juegos pequeños, y luego aprender a usar herramientas de programación con IA para ayudarte a escribir código y corregir errores. Luego, comenzando con páginas simples, crearemos gradualmente una aplicación multipágina interactiva, y añadiremos funcionalidades de IA como generación de imágenes desde texto y chat inteligente. Finalmente, completarás independientemente un proyecto completo, permitiendo que tus ideas tengan una posibilidad real de materializarse.</p><h1 id="¿por-que-usar-un-enfoque-basado-en-proyectos-para-entrenar" tabindex="-1">¿Por qué usar un enfoque basado en proyectos para entrenar? <a class="header-anchor" href="#¿por-que-usar-un-enfoque-basado-en-proyectos-para-entrenar" aria-label="Permalink to “¿Por qué usar un enfoque basado en proyectos para entrenar?”">​</a></h1><blockquote><p><strong>Desafíos del mundo real</strong></p><p>La razón es bastante simple: según el estado actual de la mayoría de los estudiantes, al entrar directamente al mundo laboral, muy probablemente tendrán dificultades bajo los &quot;golpes de la realidad&quot; de proyectos reales y jefes/clientes. Los escenarios más comunes en el mundo real son:</p></blockquote><blockquote><p>Tu mentor/jefe: Queremos hacer un xxx, el objetivo es alcanzar el efecto yyy.</p><p>¿Documentación? ¿Frameworks existentes? ¿Especificaciones detalladas de requisitos? Muchas veces no existen.</p></blockquote><p>Muchas tareas en el trabajo real consisten esencialmente en resolver problemas nunca antes vistos en un entorno de alta incertidumbre: los requisitos son vagos, los límites cambian, nadie te da la respuesta correcta, y necesitas investigar por tu cuenta, hacer experimentos, construir prototipos e iterar constantemente, para finalmente entregar una solución que &quot;funcione, sea usable y pueda ponerse en producción&quot;.</p><p>Lo que este curso quiere hacer es darte una &quot;simulación de golpes de la realidad&quot; en un entorno relativamente seguro:</p><ul><li>A través de tareas de proyecto con cierta dificultad, obligarte a practicar la descomposición de problemas, el diseño de soluciones y la búsqueda independiente de información</li><li>A través de andamios y código no tan &quot;simplificados&quot;, enseñarte a leer, entender y modificar una base de código mediana o grande</li><li>A través del ciclo completo de la idea al despliegue, hacerte experimentar el proceso completo de un producto real de 0 a 1</li></ul><p>A corto plazo, este entrenamiento es bastante exigente; pero a largo plazo, mejorará enormemente tu competitividad en la búsqueda de empleo y el desarrollo profesional: podrás soportar más presión, encontrar puntos de avance en entornos inciertos y tener más capacidad para convertir la IA en productos realmente implementados, en lugar de quedarte en la etapa de &quot;jugar con demos&quot;.</p><h1 id="el-arte-de-preguntar-una-habilidad-esencial-en-la-era-de-la-ia" tabindex="-1">El arte de preguntar: una habilidad esencial en la era de la IA <a class="header-anchor" href="#el-arte-de-preguntar-una-habilidad-esencial-en-la-era-de-la-ia" aria-label="Permalink to “El arte de preguntar: una habilidad esencial en la era de la IA”">​</a></h1><p>En la era de la IA, preguntar también es una &quot;habilidad fundamental&quot;. Con el mismo código y el mismo error, <strong>cómo preguntas casi determina qué tipo de respuesta puede dar la IA</strong>: ¿generalidades o pasos concretos y aplicables?</p><p><strong>Desarrolla buenos hábitos:</strong> Considera &quot;preguntar a la IA&quot; como parte de tu flujo de desarrollo diario: cuando no entiendas algo o estés atascado, pregunta inmediatamente.</p><h2 id="¿por-que-es-una-habilidad-esencial" tabindex="-1">¿Por qué es una habilidad esencial? <a class="header-anchor" href="#¿por-que-es-una-habilidad-esencial" aria-label="Permalink to “¿Por qué es una habilidad esencial?”">​</a></h2><ul><li><strong>Rara vez hay documentación completa en la realidad:</strong> La mayoría de las veces te enfrentas a requisitos poco claros, código a medio hacer, mensajes de error dispersos</li><li><strong>La IA es tu tutor y colega personal:</strong> Quien sabe preguntar puede convertirlo en &quot;programación en pareja de alta calidad&quot;</li><li><strong>Tu límite superior lo determina la comunicación:</strong> Cuanta más información clave puedas proporcionar y mejor puedas limitar el formato de salida, más utilizable será la respuesta</li></ul><p><strong>Error común:</strong> Preguntar solo &quot;¿por qué da error?&quot; generalmente solo genera conjeturas. Completar el contexto te dará soluciones accionables.</p><h2 id="como-alimentar-informacion-a-la-ia-captura-de-pantalla-vs-copiar-y-pegar" tabindex="-1">Cómo &quot;alimentar&quot; información a la IA: captura de pantalla vs copiar y pegar <a class="header-anchor" href="#como-alimentar-informacion-a-la-ia-captura-de-pantalla-vs-copiar-y-pegar" aria-label="Permalink to “Cómo &quot;alimentar&quot; información a la IA: captura de pantalla vs copiar y pegar”">​</a></h2><p>Ambos métodos funcionan, pero tienen usos diferentes:</p><table tabindex="0"><thead><tr><th>Método</th><th>Escenario aplicable</th><th>Requisito clave</th></tr></thead><tbody><tr><td><strong>Copiar y pegar</strong></td><td>Stack trace de errores, logs, código, configuración, respuestas de API</td><td>Intenta ser completo, no copies solo una línea clave</td></tr><tr><td><strong>Captura de pantalla</strong></td><td>Problemas de layout UI, anomalías de interacción, no encuentras botones en la interfaz de herramientas</td><td>Captura completa + anota las áreas clave, preferiblemente con una breve descripción textual</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ Requisito previo importante</p><p><strong>No todos los modelos de IA soportan entrada de imágenes.</strong> La comunicación por capturas de pantalla requiere que la IA tenga capacidades multimodales (es decir, poder entender y analizar imágenes). Actualmente, las IA que soportan entrada de imágenes incluyen: Claude (Anthropic), GPT-4V/GPT-4o (OpenAI), Gemini (Google), y algunos modelos nacionales como Tongyi Qianwen, Wenxin Yiyan, etc.</p><p><strong>Si la IA que usas no soporta entrada de imágenes</strong>, las capturas de pantalla no podrán ser reconocidas; en ese caso, usa el método de copiar y pegar texto para comunicarte.</p></div><h2 id="tecnicas-de-prompt-para-que-la-ia-explique-bien" tabindex="-1">Técnicas de prompt para que la IA &quot;explique bien&quot; <a class="header-anchor" href="#tecnicas-de-prompt-para-que-la-ia-explique-bien" aria-label="Permalink to “Técnicas de prompt para que la IA &quot;explique bien&quot;”">​</a></h2><p>Si no solo quieres la respuesta, sino &quot;aprender&quot; la respuesta. Usar instrucciones como las siguientes puede mejorar significativamente la calidad de las explicaciones:</p><blockquote><p><strong>Ejemplo de pregunta de aprendizaje</strong></p><ul><li>&quot;Por favor, primero explica este concepto en 5 frases, y luego hazme algunas preguntas para verificar que lo he entendido correctamente.&quot;</li><li>&quot;Por favor, explica detalladamente este mensaje de error, no entiendo por qué da error.&quot;</li></ul></blockquote><h1 id="he-insistido-mucho-pero-aun-no-lo-logro-quiero-rendirme" tabindex="-1">He insistido mucho pero aún no lo logro, quiero rendirme <a class="header-anchor" href="#he-insistido-mucho-pero-aun-no-lo-logro-quiero-rendirme" aria-label="Permalink to “He insistido mucho pero aún no lo logro, quiero rendirme”">​</a></h1><p>Puede que tu método de perseverancia no sea el correcto. No luches solo en la oscuridad; puedes venir a hablar con los autores y asistentes: explica honestamente los métodos que ya has probado, los puntos específicos donde estás atascado y tu estado mental actual. Muchas veces, con solo un pequeño ajuste de dirección o completar un conocimiento clave, podrás seguir avanzando.</p><h1 id="creo-que-algunos-disenos-del-tutorial-no-son-razonables" tabindex="-1">Creo que algunos diseños del tutorial no son razonables <a class="header-anchor" href="#creo-que-algunos-disenos-del-tutorial-no-son-razonables" aria-label="Permalink to “Creo que algunos diseños del tutorial no son razonables”">​</a></h1><p>Siempre eres bienvenido a contactar a los autores, crear un issue o dar retroalimentación directamente en el grupo o en clase. Esperamos mucho trabajar contigo para mejorar este tutorial: qué no está claro, qué tiene mala experiencia de usuario, qué te hizo perder tiempo, todo se puede señalar honestamente. La retroalimentación más real y específica es la que más ayuda a los futuros estudiantes a evitar errores.</p><h1 id="referencia" tabindex="-1">Referencia <a class="header-anchor" href="#referencia" aria-label="Permalink to “Referencia”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">Universidad de Nanjing, Departamento de Ciencias de la Computación y Tecnología, Curso de Fundamentos de Sistemas Informáticos</a></li></ul>',50)),d(o,{title:"Qué aprender a continuación",description:"Continúa avanzando siguiendo la ruta de 'de saber usar IA a saber crear productos'.",items:l(a)},null,8,["items"])])}}});export{b as __pageData,h as default};
